interface WashType{String name();int duration();double charge();}class Quick implements WashType{public String name(){return "Quick";}public int duration(){return 30;}public double charge(){return 20;}}class Normal implements WashType{public String name(){return "Normal";}public int duration(){return 45;}public double charge(){return 30;}}class Heavy implements WashType{public String name(){return "Heavy";}public int duration(){return 60;}public double charge(){return 45;}}class Student{String name;Student(String n){name=n;}}class WashCycle{Student student;WashingMachine machine;WashType type;WashCycle(Student s,WashingMachine m,WashType t){student=s;machine=m;type=t;}}class WashingMachine{String id;private boolean busy;WashCycle cycle;WashingMachine(String i){id=i;}boolean isBusy(){return busy;}WashCycle start(Student s,WashType t){if(busy)throw new IllegalStateException();busy=true;return cycle=new WashCycle(s,this,t);}void complete(){if(!busy)throw new IllegalStateException();busy=false;cycle=null;}}public class Main{public static void main(String[]a){}}